%% ================================================================
%  RECENT AUSTRALIAN DOLLAR APPRECIATION
%  CLASSICAL SOE-SVAR HISTORICAL DECOMPOSITION
%
%  Separate quarterly decompositions:
%
%       2025Q4 = 2025Q4 minus 2025Q3
%       2026Q2 = 2026Q2 minus 2026Q1
%
%  Uses the LOCKED historical decomposition already generated by:
%
%       svar_hd.m
%
%% ================================================================

clear;
clc;
close all;


%% 1. PATHS

folder = ...
    fileparts(mfilename('fullpath'));


resultDir = ...
    fullfile(folder,'results');


figDir = ...
    fullfile(folder,'figures');


if ~exist(figDir,'dir')
    mkdir(figDir);
end


dataFile = ...
    fullfile( ...
        folder, ...
        'data', ...
        'data_collected.xlsx');


hdFile = ...
    fullfile( ...
        resultDir, ...
        'svar_historical_decomposition.mat');


assert(isfile(hdFile), ...
    'Run svar_hd.m first: svar_historical_decomposition.mat not found.');


%% 2. LOAD LOCKED SVAR HD

S = ...
    load(hdFile);


hd = ...
    S.hd_results;


clear S


HD_grouped = ...
    hd.HD_grouped;


rtwi_actual = ...
    hd.rtwi_actual_log;


rtwi_baseline = ...
    hd.rtwi_baseline_log;


groupLabels = ...
    hd.groupLabels;


assert(size(HD_grouped,2) == 6);


%% 3. IMPORT DATES

data = readtable( ...
    dataFile, ...
    'Sheet','data', ...
    'VariableNamingRule','preserve');


data = standardizeMissing( ...
    data, ...
    {'NA','N/A','na',''});


if ~isdatetime(data.quarter_start)

    if isnumeric(data.quarter_start)

        data.quarter_start = ...
            datetime( ...
                data.quarter_start, ...
                'ConvertFrom','excel');

    else

        data.quarter_start = ...
            datetime(data.quarter_start);

    end

end


%% 4. MATCH ORIGINAL SVAR SAMPLE

sample = ...
    data.quarter_start >= datetime(1995,1,1) ...
    & data.quarter_start <= datetime(2026,4,1);


D = ...
    data(sample,:);


assert(height(D) == length(rtwi_actual), ...
    'Date sample does not match saved SVAR HD.');


%% 5. RECENT APPRECIATION EPISODE
%
% Episode includes:
%
%   2025Q4
%   2026Q1
%   2026Q2
%
% Following the convention used in svar_hd.m:
%
% contribution =
% value at end of 2026Q2
% minus value immediately before 2025Q4
%
% i.e. 2026Q2 minus 2025Q3.

episodeName = ...
    '2025Q4-2026Q2';


episodeStart = ...
    datetime(2025,10,1);


episodeEnd = ...
    datetime(2026,4,1);


i0 = ...
    find( ...
        D.quarter_start < episodeStart, ...
        1, ...
        'last');


i1 = ...
    find( ...
        D.quarter_start <= episodeEnd, ...
        1, ...
        'last');


assert(~isempty(i0) && ~isempty(i1));


fprintf('\nEpisode starts with 2025Q4 and ends at 2026Q2.\n');
fprintf('Change measured from %s to %s.\n', ...
    string(D.quarter_start(i0)), ...
    string(D.quarter_start(i1)));


%% 6. CONTRIBUTIONS

ActualChange = ...
    rtwi_actual(i1) ...
    - rtwi_actual(i0);


Contrib = ...
    nan(1,7);


% Baseline dynamics
Contrib(1) = ...
    rtwi_baseline(i1) ...
    - rtwi_baseline(i0);


% Structural contributions
Contrib(2:7) = ...
    HD_grouped(i1,:) ...
    - HD_grouped(i0,:);


AccountingError = ...
    ActualChange ...
    - sum(Contrib);


assert( ...
    abs(AccountingError) < 1e-8);


%% 7. RESULTS TABLE

componentNames = { ...
    'Baseline dynamics', ...
    'Global activity', ...
    'Commodity prices', ...
    'Global risk (VIX)', ...
    'Domestic macro', ...
    'Relative yields', ...
    'Residual FX'};


RecentSVAR = table( ...
    string(episodeName), ...
    D.quarter_start(i0), ...
    D.quarter_start(i1), ...
    ActualChange, ...
    Contrib(1), ...
    Contrib(2), ...
    Contrib(3), ...
    Contrib(4), ...
    Contrib(5), ...
    Contrib(6), ...
    Contrib(7), ...
    AccountingError, ...
    'VariableNames', ...
    { ...
    'Episode', ...
    'PreviousQuarter', ...
    'EndQuarter', ...
    'Actual_RTWI_Change', ...
    'Baseline_Dynamics', ...
    'Global_Activity', ...
    'Commodity_Prices', ...
    'VIX', ...
    'Domestic_Macro', ...
    'Relative_Yields', ...
    'Residual_FX', ...
    'Accounting_Error'});


disp(RecentSVAR);


%% 8. ORDERING-ROBUST GROUPS

CommodityRisk = ...
    Contrib(3) ...
    + Contrib(4);


YieldFX = ...
    Contrib(6) ...
    + Contrib(7);


RecentSVAR_Grouped = table( ...
    string(episodeName), ...
    ActualChange, ...
    CommodityRisk, ...
    YieldFX, ...
    'VariableNames', ...
    { ...
    'Episode', ...
    'Actual_RTWI_Change', ...
    'Commodity_plus_Risk', ...
    'RelativeYield_plus_ResidualFX'});


disp(RecentSVAR_Grouped);



%% 10. FIGURE

figure( ...
    'Color','w', ...
    'Position',[180 150 850 500]);


b = bar( ...
    1, ...
    Contrib, ...
    'stacked');


hold on;


hActual = plot( ...
    1, ...
    ActualChange, ...
    'ko', ...
    'MarkerFaceColor','k', ...
    'MarkerSize',8);


yline(0,'k:','HandleVisibility','off');


xlim([0.4 1.6]);

xticks(1);

xticklabels({'2025Q4-2026Q2'});


ylabel( ...
    'Contribution to RTWI change, log points');


title( ...
    'SVAR: What Drove the Late-2025 to Mid-2026 Appreciation?');


grid on;
box off;


legend( ...
    [b(:);hActual], ...
    [componentNames {'Observed change'}], ...
    'Location','eastoutside');


%% 11. EXPORT

exportgraphics( ...
    gcf, ...
    fullfile( ...
        figDir, ...
        '37_svar_recent_quarter_hd.png'), ...
    'Resolution',300);


outputFile = ...
    fullfile( ...
        resultDir, ...
        'svar_recent_quarter_hd.xlsx');


if isfile(outputFile)
    delete(outputFile);
end


writetable( ...
    RecentSVAR, ...
    outputFile, ...
    'Sheet','individual');


writetable( ...
    RecentSVAR_Grouped, ...
    outputFile, ...
    'Sheet','grouped');


fprintf('\nMaximum accounting error: %.3e\n', ...
    max(abs(AccountingError)));

fprintf('\nSVAR recent-quarter HD complete.\n');